IF OBJECT_ID(N'dbo.copilot_event_contexts', N'U') IS NOT NULL
   AND NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID(N'dbo.copilot_event_contexts') AND name = N'IX_copilot_chat_id')
